import{_ as r,C as s,c as n,o as d,a3 as e,G as o}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Mandatory days","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/setup/mandatory-days.md","filePath":"master/human-resources/time-off/setup/mandatory-days.md","lastUpdated":1791902625000}'),i={name:"master/human-resources/time-off/setup/mandatory-days.md"};function l(m,a,y,h,c,g){const t=s("ImagePopup");return d(),n("div",null,[a[0]||(a[0]=e('<h1 id="mandatory-days" tabindex="-1">Mandatory days <a class="header-anchor" href="#mandatory-days" aria-label="Permalink to &quot;Mandatory days&quot;">​</a></h1><p>A mandatory day is a date or range when the company expects everyone to be at work, such as a quarter close. You record it so people can see it. It has a colour, a name and two dates.</p><blockquote><p><strong>In simple words:</strong> A mandatory day is a day everyone is expected to work, kept in a list.</p></blockquote><p>Open <code>Time Off → Configuration → Mandatory Holidays</code>. The page title is <strong>Mandatory Days</strong>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Nothing is needed first. The company is filled in for you.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page lists each mandatory day. The columns are <strong>Name</strong>, <strong>Company Name</strong>, <strong>Created By</strong>, <strong>Start Date</strong> and <strong>End Date</strong>. Use the <strong>Group by</strong> list to group by <strong>Name</strong>, <strong>Created By</strong>, <strong>Company Name</strong>, <strong>Start Date</strong> or <strong>End Date</strong>. Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>.</p><p>Sample data holds one record, <strong>Company Anniversary</strong>, from Jul 26, 2025 to Jul 27, 2025.</p>',8)),o(t,{src:"/images1/time-off/to_set_mandatory_list.png",alt:"Mandatory Days list showing Company Anniversary with company, creator and dates"}),a[1]||(a[1]=e('<h2 id="create-a-mandatory-day" tabindex="-1">Create a mandatory day <a class="header-anchor" href="#create-a-mandatory-day" aria-label="Permalink to &quot;Create a mandatory day&quot;">​</a></h2><p>This example adds <strong>Quarter Close Day</strong>.</p><ol><li>Open <code>Time Off → Configuration → Mandatory Holidays</code>.</li><li>Click <strong>New Mandatory Day</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Color:</em></strong> Required. Type a hex code such as <code>#f20a0a</code> (red), or click the swatch dot and pick a colour in the panel.</li><li><strong><em>Name:</em></strong> Required. Type <code>Quarter Close Day</code>.</li><li><strong><em>Start Date:</em></strong> Required. Pick the day. Dates show like <code>Dec 31, 2026</code>.</li><li><strong><em>End Date:</em></strong> Required. Pick the same day for a one day range.</li></ul>',4)),o(t,{src:"/images1/time-off/to_set_mandatory_form.png",alt:"Create Mandatory Days window with colour #f20a0a, name Quarter Close Day and a one day range"}),a[2]||(a[2]=e('<ol start="4"><li>Click <strong>Create</strong>. The window closes and the day joins the list.</li></ol><h2 id="where-mandatory-days-show" tabindex="-1">Where mandatory days show <a class="header-anchor" href="#where-mandatory-days-show" aria-label="Permalink to &quot;Where mandatory days show&quot;">​</a></h2><p>Open the <strong>Holidays</strong> window on <code>Time Off → My Time → Dashboard</code>. The <strong>Mandatory Holidays</strong> section lists each mandatory day with its company and its start and end date and time.</p>',3)),o(t,{src:"/images1/time-off/to_set_mandatory_window.png",alt:"Holidays panel with the end of the public holiday list and the Mandatory Holidays section showing Company Anniversary"}),a[3]||(a[3]=e('<h2 id="edit-or-delete" tabindex="-1">Edit or delete <a class="header-anchor" href="#edit-or-delete" aria-label="Permalink to &quot;Edit or delete&quot;">​</a></h2><p>Click <strong>Edit</strong> to change a field, then <strong>Save changes</strong>. Click <strong>Delete</strong> to remove the day.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./public-holidays.html">Public holidays</a></li><li><a href="./">Setup</a></li><li><a href="./../requests/my-time.html">My Time</a></li></ul>',4))])}const _=r(i,[["render",l]]);export{u as __pageData,_ as default};
